{
  "avaliacoes": [
    {
      "id": "Ed1c24cdcbffc03a1",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A verificação pré-uso ou pré-içamento deve incluir a condição das lingas e do rigging, inclusive quando a carga já vier previamente eslingada por empresa locadora, pois esse arranjo pode não ter sido checado pela equipe do cais ou da embarcação.",
          "trechos": [
            "Ed1c24cdcbffc03a1:0:698"
          ],
          "condicoes": [
            "no contexto de alerta de segurança sobre quase acidente de içamento",
            "aplicável a cargas previamente eslingadas por terceiros"
          ],
          "limites": [
            "o texto apresenta recomendação de safety alert, não critério normativo universal",
            "não detalha método de inspeção nem critérios de rejeição por tipo de acessório"
          ]
        },
        {
          "proposicao": "A conferência do indicador de peso da carga é usada para verificar que a carga não excede o peso recomendado do guindaste, conectando o controle do peso informado ao uso seguro do equipamento de içamento.",
          "trechos": [
            "Ed1c24cdcbffc03a1:0:698"
          ],
          "condicoes": [
            "quando houver indicador de peso da carga no sistema",
            "no contexto de comparação com o peso recomendado do guindaste"
          ],
          "limites": [
            "a fonte não fornece valores, margens ou critérios de cálculo",
            "a recomendação decorre de um alerta de segurança específico"
          ]
        },
        {
          "proposicao": "Se o guindaste exceder sua capacidade nominal, a fonte recomenda retirá-lo de serviço e submetê-lo a inspeção e teste por mecânicos certificados para verificar se houve dano.",
          "trechos": [
            "Ed1c24cdcbffc03a1:0:698",
            "Ed1c24cdcbffc03a1:698:1020"
          ],
          "condicoes": [
            "após evento em que a capacidade nominal do guindaste tenha sido excedida"
          ],
          "limites": [
            "não trata diretamente da seleção de lingas, manilhas, ganchos, vigas ou padeyes",
            "é recomendação de autoridade estrangeira para prevenção de incidentes"
          ]
        }
      ]
    },
    {
      "id": "Eaa8039f602fd5214",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "As funções envolvidas na operação de içamento incluem verificar equipamentos de içamento e a segurança da carga antes do içamento, vinculando a checagem do conjunto carga-acessórios ao preparo operacional.",
          "trechos": [
            "Eaa8039f602fd5214:0:697"
          ],
          "condicoes": [
            "no contexto do padrão de treinamento OMHEC para operação offshore",
            "aplicável às funções listadas na matriz de responsabilidades"
          ],
          "limites": [
            "o trecho não discrimina inspeções específicas para manilhas, ganchos, vigas, padeyes ou ângulos de linga",
            "trata-se de referencial estrangeiro de treinamento, não requisito brasileiro"
          ]
        },
        {
          "proposicao": "A avaliação das condições ambientais e da influência de cargas dinâmicas integra a decisão de seguir ou não com o içamento, relacionando ambiente operacional à distribuição de esforços e ao comportamento da carga.",
          "trechos": [
            "Eaa8039f602fd5214:697:1395"
          ],
          "condicoes": [
            "na etapa de assessment de riscos e perigos",
            "especialmente para condições meteorológicas e efeitos dinâmicos"
          ],
          "limites": [
            "não fornece limites numéricos de vento, onda ou movimento",
            "não apresenta modelo de cálculo das cargas dinâmicas"
          ]
        },
        {
          "proposicao": "O padrão atribui às funções de içamento a necessidade de conhecer e avaliar a distribuição de forças, incluindo cálculo da composição de forças.",
          "trechos": [
            "Eaa8039f602fd5214:1395:1986"
          ],
          "condicoes": [
            "no escopo de capacitação das funções envolvidas na operação",
            "aplicável ao conhecimento requerido no padrão de treinamento"
          ],
          "limites": [
            "não explicita fórmulas, exemplos de ângulos de lingas nem critérios de aceitação",
            "o enunciado é de competência requerida, não demonstração experimental de desempenho"
          ]
        }
      ]
    },
    {
      "id": "E58347144f377ac23",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "SWL é definida como a carga máxima que um item de equipamento de içamento pode elevar, baixar ou sustentar sob condições particulares de serviço, conforme certificação por pessoa competente independente.",
          "trechos": [
            "E58347144f377ac23:0:693",
            "E58347144f377ac23:693:1391"
          ],
          "condicoes": [
            "sob condições particulares de serviço",
            "no contexto das definições citadas pelo padrão OMHEC e referência NORSOK"
          ],
          "limites": [
            "a definição não fornece valores nem substitui verificação específica da operação",
            "o referencial citado é estrangeiro, não requisito brasileiro"
          ]
        },
        {
          "proposicao": "O slinger é descrito como responsável por conectar e desconectar a carga ao acessório de içamento do guindaste e também pela seleção e uso corretos do gear e equipment de içamento conforme o plano operacional.",
          "trechos": [
            "E58347144f377ac23:693:1391"
          ],
          "condicoes": [
            "no contexto de funções definidas para operações de içamento",
            "em conformidade com o operating lift plan"
          ],
          "limites": [
            "o trecho define responsabilidade funcional, mas não apresenta critérios técnicos detalhados de seleção",
            "não especifica tipos de acessórios nem regras de compatibilidade"
          ]
        },
        {
          "proposicao": "Antes do início do trabalho, a toolbox talk é descrita como discussão breve entre todos os membros da operação para acordar aspectos do trabalho, sequência das etapas, perigos e métodos de controle.",
          "trechos": [
            "E58347144f377ac23:1391:2086"
          ],
          "condicoes": [
            "prévia ao commencement of work",
            "com participação dos membros da operação de içamento"
          ],
          "limites": [
            "não detalha conteúdo mínimo específico sobre ângulos, padeyes ou distribuição de esforços",
            "trata-se de enquadramento de treinamento e organização do trabalho"
          ]
        }
      ]
    },
    {
      "id": "E2a0d4afe14f55459",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "E350fef4db6b87fab",
